"""
Expression Engine — Resolves {{$input.field}} and {{$node.nodeId.field}} expressions
in node config strings before execution.

Missing keys return empty string instead of None (spec requirement).
"""

import re
import json
import logging
from typing import Any

logger = logging.getLogger(__name__)

# Regex to match {{ ... }} expressions
_EXPR_PATTERN = re.compile(r"\{\{\s*(.+?)\s*\}\}")

# Matches valid node IDs generated by the canvas (e.g. node_3, node_14).
# Used to suppress warnings for forward/self-references on first iteration.
_BARE_NODE_ID = re.compile(r"^node_\d+$")


def _resolve_path(obj: Any, path: list[str]) -> Any:
    """Walk a dot-separated path into a nested dict/list.
    If a string value is encountered mid-path, attempts JSON parsing before giving up.
    """
    current = obj
    for part in path:
        if current is None:
            return ""  # Missing key → empty string
        # If current is a string and we still have path to traverse,
        # try parsing it as JSON first (handles LLM string responses)
        if isinstance(current, str):
            try:
                current = json.loads(current)
            except (json.JSONDecodeError, ValueError):
                return ""  # Not parseable JSON — path is dead
        # Handle list index: items[0]
        bracket = re.match(r"^(\w+)\[(\d+)\]$", part)
        if bracket:
            key, idx = bracket.group(1), int(bracket.group(2))
            if isinstance(current, dict):
                current = current.get(key)
            else:
                return ""
            if isinstance(current, (list, tuple)) and idx < len(current):
                current = current[idx]
            else:
                return ""
        elif isinstance(current, dict):
            current = current.get(part, "")  # Missing key → empty string
        else:
            return ""
    return current


def resolve_expression(
    expr: str, input_data: dict[str, Any], context: dict[str, Any]
) -> Any:
    """
    Resolve a single expression string (without {{ }}).
    Missing keys return empty string instead of None.
    """
    expr = expr.strip()

    # ── $input ──
    if expr == "$input":
        return input_data
    if expr.startswith("$input."):
        path = expr[len("$input."):].split(".")
        return _resolve_path(input_data, path)

    # ── $node.nodeId.field ──
    if expr.startswith("$node."):
        parts = expr[len("$node."):].split(".", 1)
        node_id = parts[0]
        node_data = context.get(node_id)
        if node_data is None:
            return ""
        if len(parts) == 1:
            return node_data
        path = parts[1].split(".")
        return _resolve_path(node_data, path)

    # ── $item / $index / $total — For Loop iteration variables ──
    if expr == "$item":
        return input_data.get("__current_item__", context.get("__current_item__", ""))
    if expr.startswith("$item."):
        item_val = input_data.get("__current_item__", context.get("__current_item__"))
        if item_val is None:
            return ""
        path = expr[len("$item."):].split(".")
        return _resolve_path(item_val, path)
    if expr == "$index":
        return input_data.get("__for_index__", context.get("__for_index__", 0))
    if expr == "$total":
        return input_data.get("__for_total__", context.get("__for_total__", 0))

    # ── Bare shorthand: node_id.field or node_id.field[0].sub ──
    # Handles {{node_3.messages[0].content}} without requiring the $node. prefix.
    # Check context first (node outputs live there), then input_data (flat merged).
    dot = expr.find(".")
    if dot != -1:
        candidate_id = expr[:dot]
        rest = expr[dot + 1:]
        if candidate_id in context:
            path = rest.split(".")
            return _resolve_path(context[candidate_id], path)
        if candidate_id in input_data:
            path = rest.split(".")
            return _resolve_path(input_data[candidate_id], path)
        # Forward/self-reference: node hasn't produced output yet (common on
        # first iteration of published workflows).  Return "" silently.
        if _BARE_NODE_ID.match(candidate_id):
            logger.debug(f"Deferred expression (node not yet executed): {expr}")
            return ""

    # Also support bare node_id with no subpath (returns the whole node output dict)
    if expr in context:
        return context[expr]
    if expr in input_data:
        return input_data[expr]

    # ── $secret — pass through to secret_vault.resolve_config() ──────────────
    # Never resolve $secret.* here. The vault resolver runs immediately after
    # resolve_config() in orchestrator._execute_node() and handles these.
    # Eating the reference here (returning "") causes bot_token/api_key to
    # arrive at the handler as an empty string.
    if expr.startswith("$secret."):
        return f"{{{{{expr}}}}}"   # re-wrap: $secret.key → {{$secret.key}}

    # Unknown expression — return empty string
    logger.warning(f"Unknown expression: {expr}")
    return ""


def resolve_config_value(
    value: Any, input_data: dict[str, Any], context: dict[str, Any]
) -> Any:
    """
    Recursively resolve expressions in a config value.
    - Strings: replace {{...}} expressions
    - Dicts: recurse into values
    - Lists: recurse into items
    """
    if isinstance(value, str):
        # If the entire string is a single expression, return the raw value (preserving type)
        full_match = _EXPR_PATTERN.fullmatch(value)
        if full_match:
            return resolve_expression(full_match.group(1), input_data, context)

        # Otherwise, do string interpolation for embedded expressions
        def _replacer(m: re.Match) -> str:
            resolved = resolve_expression(m.group(1), input_data, context)
            if resolved is None:
                return ""
            # Dicts and lists → compact JSON so downstream templates stay valid JSON
            if isinstance(resolved, (dict, list)):
                return json.dumps(resolved, ensure_ascii=False, separators=(',', ':'))
            return str(resolved)

        return _EXPR_PATTERN.sub(_replacer, value)

    elif isinstance(value, dict):
        return {k: resolve_config_value(v, input_data, context) for k, v in value.items()}

    elif isinstance(value, list):
        return [resolve_config_value(item, input_data, context) for item in value]

    return value


def resolve_config(
    config: dict[str, Any], input_data: dict[str, Any], context: dict[str, Any]
) -> dict[str, Any]:
    """Resolve all expressions in a node's config dict."""
    return resolve_config_value(config, input_data, context)


def resolve_dotpath(path: str, context: dict) -> Any:
    """Resolve a dot-separated path (with optional [n] bracket indexing) against a context dict."""
    if not path or not isinstance(path, str):
        return ""
    parts = path.split(".")
    return _resolve_path(context, parts)


def resolve_template(value: str, input_data: dict) -> str:
    """Resolve {{ variable }} placeholders using input_data."""
    if not isinstance(value, str):
        return value

    def replacer(match):
        key = match.group(1).strip()
        val = resolve_dotpath(key, input_data)
        return str(val) if val is not None else ""

    return _EXPR_PATTERN.sub(replacer, value)


def apply_output_mapping(result: dict, mapping) -> dict:
    """
    Apply an optional output_mapping to the result dict.

    Accepts either:
      - a dict  {new_key: old_key}  (as parsed from node config)
      - a JSON string '{{"new_key": "old_key"}}'

    The mapped keys are MERGED into the original result so that
    __meta__ and other node fields are preserved.
    """
    if not mapping:
        return result

    # Accept both dict (from sanitize_config) and JSON string
    if isinstance(mapping, str):
        try:
            mapping = json.loads(mapping)
        except json.JSONDecodeError as e:
            logger.warning(
                f"output_mapping contains invalid JSON and was ignored. "
                f"Parse error at position {e.pos}: {e.msg}. "
                f"Raw value: {mapping!r}"
            )
            return result

    if not isinstance(mapping, dict):
        logger.warning(f"output_mapping must be a dict or JSON string, got {type(mapping).__name__}")
        return result

    mapped = {}
    missing_keys = []
    for new_key, old_key in mapping.items():
        if isinstance(old_key, str) and old_key in result:
            mapped[new_key] = result[old_key]
        else:
            missing_keys.append(old_key)

    if missing_keys:
        logger.warning(
            f"output_mapping: source keys not found in result: {missing_keys}. "
            f"Available keys: {list(result.keys())}"
        )

    # Merge mapped aliases into the original result (preserves __meta__, model, tokens, etc.)
    return {**result, **mapped}
